/**
 * The types `save/vault/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    VaultNodeSaveRow, VaultSaveExtract, VaultV29LevelTarget, VaultV29ProgressExtract
 * depends    —
 * used by    src/save/index, src/save/vault/index, src/save/vault/read, src/save/vault/v29-progress
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from read.ts

export interface VaultNodeSaveRow {
  /** Save array slot (`harmonyNodesUnlocked[i]` or `powerNodesLevel[i]`). */
  saveIndex: number
  id: string | null
  name: string | null
  level: number
  unlocked: boolean
  maxLevel: number | null
}

export interface VaultSaveExtract {
  keys: number | null
  totalKeysEarned: number | null
  powerNodes: VaultNodeSaveRow[]
  harmonyNodes: VaultNodeSaveRow[]
  powerUnlockedCount: number
  harmonyUnlockedCount: number
  powerLeveledCount: number
  powerLevelSum: number
  /**
   * v29 `PlayerData.vault` progress mapped to import keys (`v29:…`).
   * Null when the save predates VaultPlayerProgress.
   */
  v29: VaultV29ProgressExtract | null
  warnings: string[]
}

// from v29-progress.ts

export interface VaultV29LevelTarget {
  key: string
  maxLevel: number
}

export interface VaultV29ProgressExtract {
  /** Level keys (`v29:…`) → purchased level. */
  levels: Record<string, number>
  unlockedGroupCount: number
  upgradeCount: number
  unknownVaultIds: number[]
  unknownGroups: number[]
  warnings: string[]
}
